    if (n>=k) and (k>0):
        break;
#B2 Tính n! = 1*2*3*...*n
giai_thua_n =1;
for i in range(1, n+1):
    giai_thua_n = giai_thua_n *i;
#B3 Tính k! = 1*2*3*...*k
giai_thua_k =1;
for i in range(1, k+1):
    giai_thua_k = giai_thua_k *i;
#B4 Tính (n-k)! = 1*2*3*...*(n-k)
